 d["heap"]=ESP.getFreeHeap();d["uptime"]=millis()/1000;d["loopBusyPercent"]=cpuLoad_;d["loopUs"]=loopUs_;d["requests"]=requests_;d["multiplexer"]=sensors_.multiplexerDetected();d["developerMode"]=c.system.developerMode;
