String WebInterface::diagnosticsJson(){JsonDocument d;auto a=d["i2c"].to<JsonArray>();for(int addr=1;addr<127;addr++){Wire.beginTransmission(addr);if(Wire.endTransmission()==0)a.add(addr);}d["chipModel"]=ESP.getChipModel();d["chipRevision"]=ESP.getChipRevision();d["cpuMHz"]=ESP.getCpuFreqMHz();d["flashBytes"]=ESP.getFlashChipSize();d["heapFree"]=ESP.getFreeHeap();d["heapMin"]=ESP.getMinFreeHeap();d["sketchSize"]=ESP.getSketchSize();d["freeSketchSpace"]=ESP.getFreeSketchSpace();d["resetReason"]=esp_reset_reason();d["logs"]=logger_.text();String s;serializeJson(d,s);return s;}
bool WebInterface::applyOverrides(JsonVariantConst d){
 if(!d.is<JsonObjectConst>()||!d["colorEnabled"].is<bool>()||!d["simulation"].is<int>()||
    !d["marbleColors"].is<int>()||!d["marbleStrength"].is<int>())return false;
 RgbColor average,simulation;
 if(!parseHex(d["averageColor"]|"",average)||!parseHex(d["simulationColor"]|"",simulation))return false;
 int mode=d["simulation"].as<int>(),colors=d["marbleColors"].as<int>(),strength=d["marbleStrength"].as<int>();
 if((mode!=0&&mode!=2&&mode!=5)||colors<2||colors>255||strength<0||strength>100)return false;
 auto sensors=d["sensors"].as<JsonArrayConst>();if(sensors.size()!=MaxSensors)return false;
 DebugOverrides next=overrides_;next.colorEnabled=d["colorEnabled"].as<bool>();next.averageOnly=true;next.averageColor=average;next.exposureEnabled=false;next.exposureAll=true;
 next.simulation=(SimulationMode)mode;next.simulationColor=simulation;next.marbleColors=colors;next.marbleStrength=strength;
 size_t i=0;for(auto item:sensors){RgbColor color;if(!item.is<JsonObjectConst>()||!item["colorEnabled"].is<bool>()||!parseHex(item["color"]|"",color))return false;next.sensorColorEnabled[i]=store_.config().sensors[i].enabled&&item["colorEnabled"].as<bool>();next.sensorColors[i]=color;i++;}
 overrides_=next;return true;
}

void WebInterface::handleConfigPost(bool replace){
 if(!server_.hasArg("plain")){sendJson("{\"error\":\"body required\"}",400);return;}
 AppConfig previous=store_.config();HardwareConfig oldHardware=previous.hardware;WifiConfig oldWifi=previous.wifi;bool directWasActive=directOverride(overrides_);
 if(!store_.importJson(server_.arg("plain"),replace)){JsonDocument error;error["error"]="Invalid configuration: "+store_.lastError();String text;serializeJson(error,text);sendJson(text,400);return;}
 auto&current=store_.config();auto&newHardware=current.hardware;auto&newWifi=current.wifi;
 bool restartRequired=oldHardware.i2cSdaPin!=newHardware.i2cSdaPin||oldHardware.i2cSclPin!=newHardware.i2cSclPin||oldHardware.sensorLedPins!=newHardware.sensorLedPins||oldHardware.tcaChannels!=newHardware.tcaChannels;
 bool wifiReconnectRequired=oldWifi.ssid!=newWifi.ssid||oldWifi.password!=newWifi.password||oldWifi.hostname!=newWifi.hostname;
 bool fallbackApChanging=network_.apActive()&&
  (oldWifi.fallbackEnabled!=newWifi.fallbackEnabled||
   oldWifi.fallbackSsid!=newWifi.fallbackSsid||
   oldWifi.fallbackPassword!=newWifi.fallbackPassword);
 bool rescanRequired=sensorRuntimeChanged(previous,current),wledChanged=wledConfigChanged(previous.wled,current.wled),wledEndpointChangedNow=wledEndpointChanged(previous.wled,current.wled),authenticationChanged=previous.system.authenticationEnabled!=current.system.authenticationEnabled||previous.system.authenticationUser!=current.system.authenticationUser||previous.system.authenticationPassword!=current.system.authenticationPassword;
 bool calibrationInvalidated=false;
 if(!replace){
  bool invalidateAll=previous.light.brightness!=current.light.brightness||previous.light.activeHigh!=current.light.activeHigh;
  for(size_t i=0;i<MaxSensors;i++){
   bool changed=invalidateAll||previous.hardware.sensorLedPins[i]!=current.hardware.sensorLedPins[i]||
    previous.hardware.tcaChannels[i]!=current.hardware.tcaChannels[i]||
    previous.sensors[i].lightCorrection!=current.sensors[i].lightCorrection;
   if(changed&&(current.sensors[i].calibration.valid||current.sensors[i].calibration.brightnessValid)){
    current.sensors[i].calibration.valid=false;current.sensors[i].calibration.brightnessValid=false;calibrationInvalidated=true;
   }
  }
 }
 if(!store_.save()){store_.config()=previous;logger_.log(LogLevel::Error,"Configuration save failed");sendJson("{\"error\":\"save failed\"}",500);return;}
 bool resetAveraging=colorProcessingChanged(previous,current);
 bool directStopped=false;
 if(replace){overrides_=DebugOverrides{};if(directWasActive){engine_.stopDebugOutput();directStopped=true;}}
 else for(size_t i=0;i<MaxSensors;i++)if(!current.sensors[i].enabled)overrides_.sensorColorEnabled[i]=false;
 logger_.setLevel(current.system.logLevel);
 JsonDocument response;response["ok"]=true;response["restartRequired"]=restartRequired;response["wifiReconnectRequired"]=wifiReconnectRequired;response["fallbackApChanging"]=fallbackApChanging;response["stationConnected"]=WiFi.status()==WL_CONNECTED;response["authenticationChanged"]=authenticationChanged;response["authenticationEnabled"]=current.system.authenticationEnabled;response["calibrationInvalidated"]=calibrationInvalidated;
 JsonDocument publicConfig;if(!deserializeJson(publicConfig,store_.exportJson(false)))response["config"]=publicConfig.as<JsonVariantConst>();
 String text;serializeJson(response,text);sendJson(text);
 if(restartRequired){delay(500);ESP.restart();return;}
 if(resetAveraging)engine_.resetAveraging();
 lights_.setConfig(current);if(rescanRequired)sensors_.rescan();if(wledChanged||directStopped)syncWled(directStopped||engine_.outputOn()||engine_.darknessCutoffActive()||(engine_.automaticOffActive()&&current.vinyl.presenceDetection&&current.vinyl.offEnabled&&wledEndpointChangedNow));
 if(wifiReconnectRequired){delay(200);network_.reconnect();}
}
