 server_.on("/api/calibrate",HTTP_POST,[this](){count();if(!authorizeMutation())return;std::array<SensorCalibration,MaxSensors> previous;for(size_t i=0;i<MaxSensors;i++)previous[i]=store_.config().sensors[i].calibration;String m;bool ok=sensors_.calibrate(m);if(ok&&!store_.save()){for(size_t i=0;i<MaxSensors;i++)store_.config().sensors[i].calibration=previous[i];ok=false;m="Calibration could not be saved. Previous calibration was restored.";}if(ok)engine_.resetAveraging();else logger_.log(LogLevel::Error,m);JsonDocument d;d["ok"]=ok;d["message"]=m;String s;serializeJson(d,s);sendJson(s,ok?200:500);});
